    @pytest.mark.parametrize("format_param", ["raw", "json", "geo+json", "xml", "plain"])
    def test_get_pirep_success_with_different_formats(self, api_client, format_param):
        """Test successful PIREP retrieval with different response formats"""
        params = {
            "id": "KORD",
            "distance": 50,
            "format": format_param
        }
        
        headers = {"Accept": f"application/{format_param}" if format_param != "plain" else "text/plain"}
        
        response = api_client.get("/api/data/pirep", params=params, headers=headers)
        
        assert response.status_code == 200
        assert response.headers['Content-Type'] is not None
        
        if format_param == "json":
            assert isinstance(response.json(), list)
        elif format_param == "geo+json":
            data = response.json()
            assert "type" in data
            assert "features" in data

